/// Validate a whitespace-split command against the allowlist.
///
/// `argv[0]` must be `cargo`, `git`, or one of the read-only file utilities
/// (`ls`, `cat`, `head`, `tail`, `wc`, `find`). Cargo subcommands are limited
/// to `check`, `build`, `test`, `clippy`, `fmt`, `doc`, and `run -p hanihi-eval`.
/// Git is limited to the read-only verbs `status`, `diff`, `log`, `show`, and
/// `apply --check`. Flags that would change the working directory
/// (`--manifest-path`, `-C`/`--directory`) are rejected outright, and file
/// utilities must keep every path inside `repo_root` — the cwd is pinned to the
/// repo root and nothing may escape it.
fn check_command_argv(argv: &[String], repo_root: &Path) -> Result<(), String> {
    let Some(program) = argv.first() else {
        return Err("empty command".into());
    };
    match program.as_str() {
        "cargo" => {
            let Some(sub) = argv.get(1) else {
                return Err(
                    "cargo requires a subcommand (check, build, test, clippy, fmt, doc, run)"
                        .into(),
